### Repro Code

```TypeScript
export const truthy = <T>(value: Awaited<T>) => (value ? 1 : 2);
export const nullish = <T>(value: Awaited<T>) => value ?? 1;

export const fromPromise = async <T>(promise: Promise<T>) => {
  const value = await promise;
  return value ? 1 : 2;
};
```

### ESLint Config

```javascript
import tseslint from 'typescript-eslint';

export default [
  {
    files: ['**/*.ts'],
    languageOptions: {
      parser: tseslint.parser,
