};
type Wildcard = '*' | `${Group}.*`;
type Selector = Topic | Wildcard | `!${Exclude<Topic | Wildcard, '*'>}`;
type Matches<S extends string> = S extends '*'
  ? Topic
  : S extends `!${infer X}`
    ? Exclude<Topic, Matches<X>>
    : S extends `${infer G}.*`
