      : Extract<Topic, S>;
type UnionToIntersection<U> = (
  U extends unknown ? (u: U) => void : never
) extends (i: infer I) => void
  ? I
  : never;
type Next<T extends Topic> = UnionToIntersection<
  { [K in T]: (payload: Payloads[K]) => Promise<void> }[T]
>;
