  payload: Payloads[T],
  next: Next<T>,
) => void;
type HandlerFor<S extends Selector> = S extends '*'
  ? Handler<'*'>
  : S extends Topic
    ? Handler<S>
    : Handler<S>;
declare function subscribe<S extends Selector>(
  selector: S,
  handler: NoInfer<HandlerFor<S>>,
): void;

subscribe('a0.x', (payload, next) => {
  void next(payload);
});
```

