### Describe the regression

Original issue: https://github.com/vitejs/vite-plugin-react/issues/874

Hi! I was trying to config OXC plugins through the react plugin like we can do for babel, but it turns out that with rolldown+plugin-react we now set it up on global oxc.

My current config has this:

```js
plugins: [
    react({
      include:  ['/**/*.jsx']
      exclude: ['**/no-display-name/*.jsx'],
      babel: {
        plugins: [
          [
            'babel-plugin-styled-components',
            {
              displayName: true,
              ssr: true,
              pure: true,
            },
          ],
        ],
      },
    }),
    react({
      include: ['**/no-display-name/*.jsx'],
      babel: {
        plugins: [
          [
            'babel-plugin-styled-components',
            {
              displayName: false,
              ssr: true,
              pure: true,
            },
          ],
        ],
      },
    }),
]
```

So certain files have a different styled components config. I was also able to accomplish this with react-plugin-swc, using custom parserConfig:

```js
    react({
      parserConfig(id) {
        const shouldHaveDisplayName = !id.includes('/no-display-name/');
        if (!shouldHaveDisplayName) return undefined;
        if (id.endsWith('.js')) return {syntax: 'ecmascript', jsx: false};
        if (id.endsWith('.jsx')) return {syntax: 'ecmascript', jsx: true};
      },
      plugins: [
        [
          '@swc/plugin-styled-components',
          {ssr: true, displayName: true, pure: true},
        ],
      ],
    }),
    react({
      parserConfig(id) {
        const shouldHideDisplayNames = id.includes('/no-display-name/');
        if (!shouldHideDisplayNames) return undefined;
        if (id.endsWith('.js')) return {syntax: 'ecmascript', jsx: false};
        if (id.endsWith('.jsx')) return {syntax: 'ecmascript', jsx: true};
      },
      plugins: [
